#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sepol/policydb/policydb.h>
#include <sepol/policydb/hashtab.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"FAIL %d %s\n",__LINE__,#x);return 1;}}while(0)
static int readp(policydb_t*p,char*path){policy_file_t f;policydb_init(p);policy_file_init(&f);f.type=PF_USE_STDIO;f.fp=fopen(path,"rb");if(!f.fp)return 1;int r=policydb_read(p,&f,0);fclose(f.fp);return r;}
static int eq(avtab_ptr_t a,avtab_ptr_t b){if(memcmp(&a->key,&b->key,sizeof(a->key)))return 0;if(a->key.specified&AVTAB_XPERMS)return a->datum.xperms->specified==b->datum.xperms->specified&&a->datum.xperms->driver==b->datum.xperms->driver&&!memcmp(a->datum.xperms->perms,b->datum.xperms->perms,sizeof(a->datum.xperms->perms));return a->datum.data==b->datum.data;}
int main(int argc,char**argv){CHECK(argc==3);policydb_t a,b;CHECK(!readp(&a,argv[1])&&!readp(&b,argv[2]));CHECK(a.policyvers==b.policyvers);CHECK(ebitmap_cmp(&a.permissive_map,&b.permissive_map));for(int i=0;i<SYM_NUM;i++)CHECK(a.symtab[i].nprim==b.symtab[i].nprim);
 unsigned existing=0,added=0,expectedAdded=0;type_datum_t*gt=hashtab_search(a.p_types.table,"gpu_device");CHECK(gt);for(unsigned i=0;i<a.te_avtab.nslot;i++)for(avtab_ptr_t n=a.te_avtab.htable[i];n;n=n->next){int found=0;for(avtab_ptr_t m=avtab_search_node(&b.te_avtab,&n->key);m;m=avtab_search_node_next(m,n->key.specified))if(eq(n,m)){found=1;break;}CHECK(found);existing++;if(n->key.target_type==gt->s.value&&n->key.specified==AVTAB_XPERMS_ALLOWED&&n->datum.xperms->specified==AVTAB_XPERMS_IOCTLFUNCTION&&n->datum.xperms->driver==0x50)expectedAdded++;}
 type_datum_t*t=hashtab_search(b.p_types.table,"gpu_device");class_datum_t*c=hashtab_search(b.p_classes.table,"chr_file");CHECK(t&&c);
 for(unsigned i=0;i<b.te_avtab.nslot;i++)for(avtab_ptr_t n=b.te_avtab.htable[i];n;n=n->next){int found=0;for(avtab_ptr_t m=avtab_search_node(&a.te_avtab,&n->key);m;m=avtab_search_node_next(m,n->key.specified))if(eq(n,m)){found=1;break;}if(found)continue;CHECK(n->key.specified==AVTAB_XPERMS_ALLOWED&&n->key.target_type==t->s.value&&n->key.target_class==c->s.value);avtab_extended_perms_t*x=n->datum.xperms;CHECK(x->specified==AVTAB_XPERMS_IOCTLFUNCTION&&x->driver==9);uint32_t expected[8]={0};unsigned req[]={2,7,0x13,0x14,0x33,0x34,0x35,0x3b,0x47,0x48,0x4a};for(unsigned j=0;j<11;j++)expected[req[j]/32]|=1u<<(req[j]%32);CHECK(!memcmp(expected,x->perms,sizeof(expected)));added++;}
 printf("POLICY_VERIFIED existing_rules=%u added_kgsl_rules=%u existing_permissions_unchanged=1 permissive_unchanged=1 symbols_unchanged=1\n",existing,added);int valid=added==expectedAdded&&existing+added==b.te_avtab.nel;policydb_destroy(&a);policydb_destroy(&b);return valid?0:1;}
